const $=id=>document.getElementById(id);
let SQL,db,target,found=false,consultas=0,pistas=0;
const hints=['O tratador lembra que a presença na lista de refeições pendentes não significa que o animal passou o dia inteiro sem comer.','Compare os contadores: alguns animais comeram, mas ainda não completaram a rotina diária. Você procura uma situação diferente.'];
function message(text,type=''){$('feedback').textContent=text;$('feedback').className=type;}
function route(){const labels=['Investigue os registros','Descubra o animal','Registre o cuidado'];$('steps').replaceChildren();labels.forEach((label,i)=>{const div=document.createElement('div');div.className='step'+((!found&&i===0)||(found&&i===2)?' active':'');const b=document.createElement('b');b.textContent=found&&i<2?'✓':i+1;const span=document.createElement('span');span.textContent=label;div.append(b,span);$('steps').append(div);});$('mission-number').textContent='INVESTIGAÇÃO LIVRE';$('mission-title').textContent=found?'Mistério resolvido!':'Siga os dados, não um roteiro';$('mission-text').textContent=found?'Você identificou o animal. Agora registre suas refeições e consulte o contador para acompanhar o cuidado.':'Consulte a tabela animais e encontre quem passou o dia sem receber comida. Escolha suas próprias pesquisas: não é necessário seguir etapas nem usar as pistas.';}
function render(results){$('results').replaceChildren();if(!results.length){$('row-count').textContent='0 registros';$('results').textContent='Nenhum registro encontrado. Revise sua investigação.';return;}const r=results[0];$('row-count').textContent=`${r.values.length} registro${r.values.length===1?'':'s'}`;const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');r.columns.forEach(c=>{const th=document.createElement('th');th.textContent=c;tr.append(th);});head.append(tr);table.append(head);const body=document.createElement('tbody');r.values.forEach(row=>{const tr=document.createElement('tr');row.forEach(v=>{const td=document.createElement('td');td.textContent=v===null?'NULL':String(v);tr.append(td);});body.append(tr);});table.append(body);$('results').append(table);}
function counter(){return db.exec(`SELECT vezes_alimentado FROM animais WHERE id=${target.id}`)[0].values[0][0];}
function care(){const n=counter();$('rescue-text').textContent=`${target.animal} · ${target.especie} · ${n} de 3 refeições registradas hoje.`;$('feed').disabled=n>=3;$('feed').textContent=n>=3?'Três refeições registradas ✓':'Registrar uma alimentação (+1)';}
function identified(r){if(!r||r.values.length!==1)return false;const i=r.columns.indexOf('id'),a=r.columns.indexOf('animal');return (i>=0&&r.values[0][i]===target.id)||(a>=0&&r.values[0][a]===target.animal);}
function execute(){const q=$('query').value.trim();if(!q){message('Digite sua consulta SQL.','error');return;}try{if(!/^\s*SELECT\b/i.test(q))throw Error('Use SELECT para consultar os registros.');if(/\b(?:INSERT|UPDATE|DELETE|DROP|ALTER|CREATE|ATTACH|DETACH|PRAGMA|REPLACE)\b/i.test(q.replace(/'(?:''|[^'])*'/g,"''")))throw Error('Use apenas consultas SELECT.');let count=0;for(const s of db.iterateStatements(q))count++;if(count!==1)throw Error('Execute uma consulta por vez.');const results=db.exec(q);consultas++;render(results);if(!found&&identified(results[0])){found=true;$('celebration').hidden=false;$('winner-name').textContent=`Você encontrou ${target.animal}!`;$('winner-details').textContent=`Esse animal não recebeu nenhuma refeição. Mistério resolvido com ${consultas} consulta${consultas===1?'':'s'} e ${pistas} pista${pistas===1?'':'s'}.`;$('rescue').hidden=false;$('hint').disabled=true;route();care();message('Parabéns! Você resolveu o mistério do zoológico. 🏆','success');}else if(found&&identified(results[0])&&counter()===3){message('Cuidado confirmado! O animal recebeu as três refeições de hoje. 🐾','success');}else message(`Consulta ${consultas} executada. Analise os registros e escolha seu próximo passo.`);}catch(e){message('Vamos ajustar: '+e.message,'error');}}
$('run').onclick=execute;$('hint').onclick=()=>{if(pistas>=hints.length)return;$('hint-text').hidden=false;$('hint-text').textContent=hints[pistas++];$('hint').textContent=pistas===hints.length?'Duas pistas consultadas':'💡 Consultar a última pista';$('hint').disabled=pistas>=hints.length;};
$('example').onclick=()=>{$('hint-text').hidden=false;$('hint-text').textContent='SELECT escolhe as colunas, FROM informa a tabela e WHERE aplica uma condição. Você define as colunas e o filtro para investigar. Não há uma única sequência obrigatória.';};
$('query').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();if(db)execute();}});
$('feed').onclick=()=>{if(!found)return;db.run(`UPDATE animais SET vezes_alimentado=vezes_alimentado+1 WHERE id=${target.id} AND vezes_alimentado<3`);care();message(counter()===3?'Três refeições registradas! Consulte o animal para conferir.':'Alimentação registrada. Cada clique soma uma refeição.','success');};
function reset(){if(db)db.close();db=new SQL.Database();db.run('CREATE TABLE animais (id INTEGER PRIMARY KEY, animal TEXT NOT NULL UNIQUE, especie TEXT NOT NULL, vezes_alimentado INTEGER NOT NULL CHECK(vezes_alimentado BETWEEN 0 AND 3))');target=ANIMAIS[Math.floor(Math.random()*ANIMAIS.length)];const stmt=db.prepare('INSERT INTO animais VALUES (?, ?, ?, ?)');for(const a of ANIMAIS)stmt.run([a.id,a.animal,a.especie,a.id===target.id?0:Math.max(1,a.vezes_alimentado)]);stmt.free();found=false;consultas=0;pistas=0;$('query').value='';$('hint').disabled=false;$('hint').textContent='💡 Ouvir uma pista do tratador';$('hint-text').hidden=true;$('rescue').hidden=true;$('celebration').hidden=true;$('results').innerHTML='<div class="empty">🔎<p>O mistério está nos registros. Por onde você vai começar?</p></div>';$('row-count').textContent='Nenhuma consulta ainda';route();message('Banco pronto. Há exatamente um animal sem refeições. A cada reinício, o animal pode mudar.');}
$('restart').onclick=()=>{if(db&&confirm('Iniciar um novo caso? Os registros e as refeições serão reiniciados.'))reset();};route();initSqlJs({locateFile:f=>'vendor/'+f}).then(engine=>{SQL=engine;reset();$('run').disabled=false;$('run').textContent='Executar consulta →';}).catch(()=>message('Não foi possível carregar o banco. Recarregue a página.','error'));
